{
  "objective": "最小化结到环境的热阻 R_th [°C/W]；约束不满足时按违反度优先处理",
  "variables": [
    {
      "name": "n_fins",
      "min": 3.0,
      "max": 15.0,
      "unit": "片",
      "integer": true
    },
    {
      "name": "fin_height_mm",
      "min": 10.0,
      "max": 40.0,
      "unit": "mm",
      "integer": false
    },
    {
      "name": "fin_thickness_mm",
      "min": 2.0,
      "max": 6.0,
      "unit": "mm",
      "integer": false
    },
    {
      "name": "base_thickness_mm",
      "min": 2.0,
      "max": 10.0,
      "unit": "mm",
      "integer": false
    }
  ],
  "variables_note": "对外全部使用毫米与片；内部一律按 SI 计算。simulate_design / verify_design 的参数名与本列表一致",
  "constraints": {
    "t_max_limit_c": 85.0,
    "mass_limit_g": 150.0,
    "min_fin_gap_mm": 2.0,
    "envelope_mm": {
      "width": 60.0,
      "height": 50.0,
      "depth": 60.0
    }
  },
  "physics": {
    "material": "铝合金",
    "k_w_per_mk": 200.0,
    "h_convection_w_per_m2k": 12.0,
    "ambient_c": 25.0,
    "chip_power_w": 20.0,
    "density_kg_per_m3": 2700.0,
    "model": "二维截面稳态热传导，格心有限体积离散 + 稀疏直接求解；基板底面施加热流，其余表面自然对流"
  },
  "mesh": {
    "nx": 120,
    "ny": 100,
    "cell_mm": 0.5
  },
  "available_methods": [
    "random（随机搜索基线）",
    "adaptive（自适应邻域搜索）"
  ]
}
